const validPlexRun = `-- name: ValidPlexRun :one
SELECT EXISTS(SELECT 1 FROM plex_sync_runs r
JOIN plex_connections c ON c.id=r.connection_id
JOIN users admin ON admin.id=c.authorized_by AND admin.is_admin=1
JOIN users actor ON actor.id=r.actor_id AND actor.is_admin=1
WHERE r.id=? AND r.fence=? AND r.status='running' AND c.generation=r.generation
AND c.credential_ref IS NOT NULL AND c.source_epoch=r.source_epoch AND r.lease_until > ?3)
`

type ValidPlexRunParams struct {
	ID    int64  `json:"id"`
	Fence int64  `json:"fence"`
	Now   string `json:"now"`
}

func (q *Queries) ValidPlexRun(ctx context.Context, arg ValidPlexRunParams) (bool, error) {
	row := q.db.QueryRowContext(ctx, validPlexRun, arg.ID, arg.Fence, arg.Now)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
